"""Freeze two finite research questions before inspecting confirmation outcomes."""
from pathlib import Path
import hashlib,json,sys
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT))
from study005_run import baseline

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def put(p,v):
    assert not Path(p).exists(),p
    Path(p).write_text(json.dumps(v,sort_keys=True,indent=2)+'\n')
if __name__=='__main__':
    for sid in ('010','011'):
        assert not (ROOT/f'experiment-study{sid}.json').exists()
        assert not (ROOT/f'artifacts/interpretability/study-{sid}-final').exists()
    frozen=json.loads((ROOT/'preservation-010-011-initial.json').read_text())
    for n,h in frozen.items():assert sha(ROOT/n)==h,n
    *_,gate,pres=baseline()
    assert gate['model_sha256']=='fe180f8a931f9d92d8aa39da337bc819d0dbe4e6d971edcba00324fbc18a91c1'
    put(ROOT/'baseline-study010-011.json',gate)
    common=dict(source_model_sha256=gate['model_sha256'],baseline_sha256=sha(ROOT/'baseline-study010-011.json'),preservation_sha256=sha(ROOT/'preservation-010-011-initial.json'),domain='627 previously trained/audited canonical legal nonterminal boards; 4520 unique raw boards; no new-domain generalization',arithmetic='Frozen deployed CPU exact integer contract; no parameter changes, training or target execution',limits='Host CPU only; no main writes, deployment edits, services, installs or publication',offline_labels='Independent geometry and minimax used only in offline census/audit',maximum_seconds=3600)
    put(ROOT/'experiment-study010.json',dict(common,study='research010, NOT accepted C64 application010',question='How much D4 full-set symmetry is provided by the network versus the canonicalizing wrapper?',transforms='All 8 D4 source-to-destination permutations, each of 627 canonical boards; identity first. Evaluate frozen network directly on 4520 deduplicated occupancy inputs WITHOUT canonicalization, index back to 5016 orbit observations.',metrics=['full legally masked set equality after inverse mapping to original canonical coordinates','raw-coordinate fixed-priority chosen optimality, empty sets, nonoptimal nonempty choices, full-set changes, optimal tie changes separately','exact aligned logits; spatial-axis stage equality, attention both query and key axes','route order/membership and gates; nonspatial latent units have NO invented permutation'],controls=['saved target baseline627/13167/5643 first','permutation inverse and square axes tests all8','identity all-stage no-op','canonicalized wrapper4520 full-set and original-coordinate ties unchanged','deduplicated direct batch versus per-transform execution'],alignment=dict(square_rows=['board_embedding','board_normalized','board_query','board_key','board_value','attended','projected','attention_residual'],both_square_axes=['attention_scores','attention_probs'],square_output=['logits'],no_square_axis=['readout_pre','readout_gelu','norm2_output','router_scores','routes','gates','expert_hidden_pre','expert_hidden','expert_outputs','merged']),examples='First canonical ID with any nonidentity full-set disagreement, else first ID with nonidentity logit disagreement, else ID0. Show all8 transforms; no expansion.',warning='Noncanonical orientations are OFF-CONTRACT inputs for canonical-trained network. Direct failures are NOT failures of shipping wrapper. Fixed selected-move tie priority is not D4 equivariant. No claim of learned hidden invariance from wrapper outputs.'))
    stages=['board_embedding','board_normalized','board_query','board_key','board_value','attention_scores','attention_probs','attended','projected','attention_residual','readout_pre','readout_gelu','norm2_output','router_scores','routes','unordered_routes','gates','pair_and_gates','executed_expert_hidden_pre','executed_expert_hidden','executed_expert_outputs','merged','logits','unmasked_signs','legal_sign_set']
    put(ROOT/'experiment-study011.json',dict(common,study='011',question='Which exact finite-domain representations collapse board distinctions, and which routing patterns are too coarse to identify independent tactics?',stages=stages,serialization='C-order shape-prefixed signed little-endian int64 for full integer stage vectors. Boolean signs as integers. SHA256 buckets plus complete byte equality checks; independent tuple-key census. routes are ordered except explicit unordered_routes. Pair+gates concatenates ordered IDs and corresponding integer gates. Executed aggregate expert stages serialize per expert ID ascending, active mask and values for active IDs only; inactive values null in records, never observations of zero. Additional per-expert applicable-population census.',labels=['has_win','must_block','has_fork','has_opponent_fork','has_fork_prevention','complete_optimal_set'],controls='Unconditioned and conditioned on ply, side, own/opponent corner/edge/center counts. Report repeated boards in classes, class count, colliding pairs, classes differing in independent tactic tuple, and classes differing in complete optimal set. Compare logits, unmasked signs and legal mask separately.',examples='Per stage first lexicographic board pair in same exact class with different tactic tuple; independently first differing complete optimal-set pair. Keep first12 for diagram index, retain ALL classes/pairs metadata. No projection-as-proof.',warning='Cardinality/injectivity is not semantic decoding, causal use, or proof of strategic specialization. Small router cardinality is architectural and not proof of ignorance. Legal sets can differ for identical raw logits through external legal masks. Reused boards/canonical orientations are not independent observations.'))
    print(json.dumps(dict(prior_files=len(frozen),baseline=gate,manifests=['experiment-study010.json','experiment-study011.json']),indent=2))
